(() => {
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const states=new Map(),KEY='ropad.trade.pending.v1',ADDRESS=/^0x[0-9a-f]{40}$/i,HASH=/^0x[0-9a-f]{64}$/i;
  function state(build){if(!states.has(build.id))states.set(build.id,{side:'buy',amount:'',slippage:100,quote:null,market:null,error:'',busy:false,root:null});return states.get(build.id);}
  function token(build){return build.token||build.coin||{};}
  function pending(build){try{const v=JSON.parse(localStorage.getItem(KEY)||'{}')[build.id];return v&&typeof v.intentId==='string'&&(!v.hash||HASH.test(v.hash))?v:null;}catch{return null;}}
  function savePending(build,value){const all=JSON.parse(localStorage.getItem(KEY)||'{}');if(value)all[build.id]=value;else delete all[build.id];localStorage.setItem(KEY,JSON.stringify(all));}
  async function read(url,body){const headers={};if(body){const r=await fetch('/api/status',{credentials:'same-origin'}),s=await r.json();headers['X-Parallax-Token']=s.csrf;headers['Content-Type']='application/json';}const r=await fetch(url,{method:body?'POST':'GET',headers,body:body?JSON.stringify(body):undefined,credentials:'same-origin',signal:AbortSignal.timeout(60000)});const p=await r.json();if(!r.ok)throw new Error(p.error||'Trading service unavailable');return p;}
  function money(value){if(value==null||!/^\d+$/.test(String(value)))return '—';const n=Number(value)/1e6;return Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:n<1?6:2}).format(n):'—';}
  function render(build){
    const s=state(build),t=token(build),address=t.address||t.tokenAddress,verified=t.verified===true&&t.chainId===4663&&ADDRESS.test(address||''),p=pending(build),q=s.quote,wallet=window.RopadWallet?.get();
    const tab=side=>`<button type="button" data-trade-side="${side}" role="tab" aria-selected="${s.side===side}" ${s.busy||p?'disabled':''}>${side==='buy'?'Buy':'Sell'}</button>`;
    let body;
    if(!verified)body=`<div class="r-trade-empty"><strong>Pre-launch workspace</strong><p>Buy and sell opens when this game has a confirmed coin launch</p><button class="button" type="button" data-trade-launch>Launch a game coin ↗</button></div>`;
    else body=`<dl class="r-trade-metrics"><div><dt>Market cap</dt><dd>${money(s.market?.price?.marketCapMicroUsd)}</dd></div><div><dt>Token price</dt><dd>${money(s.market?.price?.priceMicroUsd)}</dd></div></dl><div role="tablist" class="r-trade-tabs" aria-label="Trade direction">${tab('buy')}${tab('sell')}</div><label class="r-trade-amount">You pay <span>${s.side==='buy'?'ORBIO':esc(t.symbol||'TOKEN')}</span><input name="tradeAmount" aria-label="Trade amount" inputmode="decimal" autocomplete="off" placeholder="0.00" value="${esc(s.amount)}" ${s.busy||p?'disabled':''}></label><label class="r-trade-slippage">Slippage<select name="tradeSlippage" aria-label="Trade slippage" ${s.busy||p?'disabled':''}>${[[50,'0.5%'],[100,'1%'],[200,'2%'],[500,'5%']].map(([v,label])=>`<option value="${v}" ${s.slippage===v?'selected':''}>${label}</option>`).join('')}</select></label>${q?`<div class="r-trade-quote"><span>${q.kind==='swap'?'SWAP PREVIEW':q.kind==='reset_approval'?'RESET EXISTING ALLOWANCE':'EXACT TOKEN APPROVAL'}</span><dl><div><dt>Expected receive</dt><dd>${esc(q.expectedOut)} ${esc(q.outputSymbol)}</dd></div><div><dt>Minimum / full-input equivalent</dt><dd>${esc(q.minimumOut)} ${esc(q.outputSymbol)}</dd></div><div><dt>Fees / creator tax</dt><dd>${q.feeBps/100}% / ${q.creatorTaxBps/100}%</dd></div><div><dt>Estimated network fee</dt><dd>${esc(q.estimatedGasEth)} ETH</dd></div></dl>${q.snipeTaxBps?`<p>Opening buy tax ${q.snipeTaxBps/100}%</p>`:''}${q.partialFill?`<p>Partial fill near graduation · Estimated refund ${esc(q.refund)} ORBIO Minimum protects the rate; filled quantity may be lower</p>`:''}${q.kind!=='swap'?`<p>Allow the registered curve to spend ${esc(q.approvalAmount)} ${esc(q.inputSymbol)} Then review a fresh swap quote</p>`:''}<small>Buys may fill partially near graduation Minimum protects the rate, not a guaranteed token quantity</small><small>Simulation passed · Quote expires ${new Date(q.expiresAt).toLocaleTimeString()}</small></div>`:''}${p?`<div class="r-trade-pending"><strong>${p.hash?'Transaction submitted':'Wallet request pending'}</strong><p>${p.hash?'Check the receipt before submitting anything else':'Resolve the open wallet request before starting another trade'}</p>${p.hash?`<a href="https://robin.etherscan.io/tx/${esc(p.hash)}" target="_blank" rel="noopener">View transaction ↗</a><button type="button" class="button" data-trade-receipt ${s.busy?'disabled':''}>Check receipt</button>`:`<label>Submitted transaction hash<input name="recoverHash" aria-label="Submitted transaction hash" placeholder="0x…"></label><button type="button" class="button" data-trade-recover>Check submitted transaction</button><button type="button" class="r-trade-link" data-trade-cancel>Wallet request was cancelled</button>`}</div>`:`<button type="button" class="button r-trade-submit ${s.side}" data-trade-submit ${s.busy?'disabled':''}>${s.busy?'Checking transaction…':!wallet?'Connect wallet':wallet.chainId!=='0x1237'?'Switch to Robinhood Chain':q?(Date.now()>q.expiresAt?'Refresh expired quote':q.kind==='swap'?'Confirm '+s.side+' in wallet':q.kind==='reset_approval'?'Reset allowance in wallet':'Approve '+q.approvalAmount+' '+q.inputSymbol):'Review '+s.side+' quote'}</button>`}<p class="r-trade-network">Robinhood Chain · Uses real ORBIO + ETH gas</p><a class="r-trade-link" href="https://www.ponsfamily.com/launchpad/${esc(address)}" target="_blank" rel="noopener">Open market on Pons ↗</a>`;
    return `<section class="r-trade-panel"><header><span>GAME COIN</span><b>${verified?'$'+esc(t.symbol||'TOKEN'):'NOT LAUNCHED'}</b></header>${body}<p class="r-trade-feedback ${s.error?'is-error':''}" role="status">${esc(s.error||s.message||'')}</p>${verified?`<small class="r-trade-source">${s.marketAt?'Orbio market data · '+new Date(s.marketAt).toLocaleTimeString():'Live market data pending'}<br>Curve trades here · Graduated pools open on Pons</small>`:''}</section>`;
  }
  function redraw(build){const s=state(build);if(!s.root?.isConnected)return;s.root.innerHTML=render(build);wire(build,s.root,false);}
  function quoteReset(build){const s=state(build);s.quote=null;s.error='';s.message='';}
  async function checkReceipt(build){const s=state(build),p=pending(build);if(!p?.hash)return;await window.RopadWallet.authenticate();const w=window.RopadWallet.get();if(w.address!==p.owner)throw Error('Connect the wallet that submitted this transaction');const r=await read('/api/orbio/trades/receipt',{intentId:p.intentId,hash:p.hash});if(r.status==='pending'){s.message='Transaction is pending confirmation';return;}savePending(build,null);s.quote=null;s.message=r.status==='confirmed'?(r.kind==='swap'?'Trade confirmed on Robinhood Chain':'Allowance confirmed Review a fresh swap quote'):'Transaction reverted No successful trade was recorded';s.marketAt=0;}
  async function action(build,fn){const s=state(build);if(s.busy)return;s.busy=true;s.error='';redraw(build);try{await fn();}catch(e){s.error=e.code===4001?'Wallet request cancelled':e.message||'The action did not complete';}finally{s.busy=false;redraw(build);}}
  function wire(build,root,load=true){const s=state(build);s.root=root;
    root.querySelector('[data-trade-launch]')?.addEventListener('click',()=>window.openRobloxLaunch?.({name:build.gameName,brief:build.brief,modelId:build.modelId,inspiration:build.inspiration}));
    root.querySelectorAll('[data-trade-side]').forEach(b=>b.onclick=()=>{s.side=b.dataset.tradeSide;quoteReset(build);redraw(build);});
    root.querySelector('[name="tradeAmount"]')?.addEventListener('input',e=>{s.amount=e.target.value;quoteReset(build);root.querySelector('.r-trade-quote')?.remove();const b=root.querySelector('[data-trade-submit]');if(b)b.textContent='Review '+s.side+' quote';});
    root.querySelector('[name="tradeSlippage"]')?.addEventListener('change',e=>{s.slippage=Number(e.target.value);quoteReset(build);redraw(build);});
    root.querySelector('[data-trade-submit]')?.addEventListener('click',()=>action(build,async()=>{
      const wallet=window.RopadWallet?.get();if(!wallet){window.RopadWallet?.connect();return;}if(wallet.chainId!=='0x1237'){await window.RopadWallet.switchChain();return;}
      if(pending(build))throw Error('Check the pending transaction first');
      await window.RopadWallet.authenticate();await window.RopadWallet.check();
      if(!s.quote||Date.now()>s.quote.expiresAt){s.quote=await read('/api/orbio/trades/quote',{buildId:build.id,side:s.side,amount:s.amount,slippageBps:s.slippage});return;}
      const q=s.quote;if(q.owner!==wallet.address||q.transaction.from!==wallet.address||q.chainId!==4663||q.transaction.chainId!=='0x1237'||q.simulation!=='passed'||!q.realFunds)throw Error('The quote no longer matches this wallet');
      // Save before opening the wallet. A dropped response must never trigger another send.
      savePending(build,{intentId:q.intentId,owner:q.owner,stage:'wallet_request',createdAt:Date.now()});redraw(build);
      let hash;try{hash=await wallet.provider.request({method:'eth_sendTransaction',params:[q.transaction]});}catch(e){if(e.code===4001)savePending(build,null);throw e;}
      if(!HASH.test(hash||''))throw Error('The wallet did not return a transaction hash Check it in your wallet before retrying');
      savePending(build,{intentId:q.intentId,owner:q.owner,hash,createdAt:Date.now()});s.quote=null;await checkReceipt(build);
    }));
    root.querySelector('[data-trade-receipt]')?.addEventListener('click',()=>action(build,()=>checkReceipt(build)));
    root.querySelector('[data-trade-recover]')?.addEventListener('click',()=>{const hash=root.querySelector('[name="recoverHash"]').value.trim();action(build,async()=>{if(!HASH.test(hash))throw Error('Enter the transaction hash from your wallet');savePending(build,{...pending(build),hash});await checkReceipt(build);});});
    root.querySelector('[data-trade-cancel]')?.addEventListener('click',()=>{savePending(build,null);quoteReset(build);redraw(build);});
    const t=token(build),address=t.address||t.tokenAddress;
    if(load&&t.verified&&ADDRESS.test(address||'')&&!s.marketLoading&&Date.now()-(s.marketAt||0)>30000){s.marketLoading=true;read('/api/orbio/agents/'+address).then(p=>{s.market=p.data;s.marketAt=Date.now();}).catch(()=>{s.market=null;s.message='Market data is currently unavailable';s.marketAt=Date.now();}).finally(()=>{s.marketLoading=false;redraw(build);});}
  }
  window.ParallaxOrbio={...(window.ParallaxOrbio||{}),buildTradePanel:render,wireBuildTradePanel:wire};
  window.addEventListener('parallax-evm-wallet-change',()=>{for(const [id,s]of states){s.quote=null;s.error='';if(s.root?.isConnected){const b=window.ParallaxBuilders?.refresh;b?.();}}});
})();
